// Poll window: last successful run, minus an overlap, in RFC 3339 as tasks.list requires.
// First run has no watermark, so it reaches back 24h rather than pulling a lifetime of tasks.
const wf = $getWorkflowStaticData('global');
const cfg = $input.first().json;
const overlapMs = (cfg.OVERLAP_MINUTES ?? 2) * 60 * 1000;

const last = wf.lastPollIso ? Date.parse(wf.lastPollIso) : null;
const since = last === null
  ? Date.now() - 24 * 60 * 60 * 1000
  : last - overlapMs;

// Stamped BEFORE the fetch, not after. If the fetch fails the watermark must not advance,
// and if it succeeds anything written during the request is covered by the next overlap.
wf.pendingPollIso = new Date().toISOString();

return [{ json: { ...cfg, updatedMin: new Date(since).toISOString() } }];

// Shape each task into the CurrentItem the app already understands
// (src/lib/rdf/current-ranking.ts). Nothing is interpreted here: the title is carried
// verbatim, because what you dictated is a fact and what it MEANT is a reading the review
// queue exists to gate.
const cfg = $('Config').first().json;
const now = new Date().toISOString();

const out = [];
for (const item of $input.all()) {
  const t = item.json;
  if (!t || !t.id) continue;

  const title = (t.title || '').trim();
  // A task with no title is a Google artifact, not something a person said.
  if (!title) continue;

  out.push({
    json: {
      externalId: t.id,
      title,
      url: t.selfLink || `https://tasks.google.com/task/${t.id}`,
      summary: (t.notes || '').trim() || undefined,
      publishedAt: t.updated || t.due || now,
      sourceLabel: 'Google Tasks',
      currentSlug: cfg.CURRENT_SLUG,
      graphStableId: cfg.GRAPH_STABLE_ID,
      fetchedAt: now,
      capturedVia: 'google-tasks'
    }
  });
}
return out;

// Advance the watermark ONLY now, on the success path. A failed fetch leaves lastPollIso
// where it was, so the next run re-covers the gap instead of stepping over it.
const wf = $getWorkflowStaticData('global');
if (wf.pendingPollIso) {
  wf.lastPollIso = wf.pendingPollIso;
  delete wf.pendingPollIso;
}
return [{ json: { ok: true, watermark: wf.lastPollIso, written: $input.all().length } }];
